class School:
    def __init__(self):
        self._students = {}
        self._added = []

    def add_student(self, name, grade):
        for names in self._students.values():
            if name in names:
                self._added.append(False)
                return False
        if grade not in self._students:
            self._students[grade] = []
        self._students[grade].append(name)
        self._added.append(True)
        return True

    def roster(self):
        result = []
        for grade in sorted(self._students):
            result.extend(sorted(self._students[grade]))
        return result

    def grade(self, grade_number):
        return sorted(self._students.get(grade_number, []))

    def added(self):
        return self._added
